{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Elbasvir, the closest structural analogue to the query, has an absolute oral bioavailability of approximately 32% in HCV-infected subjects, which is above the 20% threshold and supports a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ledipasvir, another HCV NS5A inhibitor with moderate structural transferability, shows an oral bioavailability of about 53%, supporting high oral bioavailability for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Acalabrutinib, despite lower structural similarity, has an absolute oral bioavailability of 25%, providing additional but weaker support that the 20% threshold is exceeded.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a daclatasvir-like HCV NS5A inhibitor. The closest analogue elbasvir has absolute F ~32%, and ledipasvir has F ~53%, both clearly above 20%. Distant chemotypes also mostly show F >20%, while no transferable evidence supports F <20%. Therefore the prediction is high.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself is provided.",
    "The closest analogues are not identical to the query, so exact F may differ, though the threshold-relevant direction is consistent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

